window.VeilGardeData.files["Sources-VeilGardeLens"] = {"group":"Sources-VeilGardeLens","files":[{"path":"Sources/VeilGardeLens/Capture/CaptureLens.swift","status":"added","lang":"swift","hunks":[[1,0,1,171]],"header":{"lines":[1,15],"target":"VeilGardeLens","what":[6,9],"pin":[10,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":309,"scopes":[["E","CaptureLens",null,"public",23,23,[23,24],171,null,-1,0,"a",[]],["f","reading",["_"],"public static",26,26,[26,69],33,[24,25],0,0,"a"],["f","features",["_"],"public static",36,36,[36,71],36,[35,35],0,8,"a"],["f","signature",["_"],"public static",39,39,[39,73],39,[38,38],0,8,"a"],["f","compute",["_"],"static",41,41,[41,64],90,null,0,0,"a"],["f","radialProfile",["_","h","w"],"static",93,93,[93,72],107,[92,92],0,0,"a"],["f","stddev",["_"],"static",110,110,[110,46],119,[109,109],0,0,"a"],["f","cfaSubgridTrace",["_","win"],"static",122,122,[122,67],139,[121,121],0,0,"a"],["f","lag1HorizCorr",["_","win"],"static",142,142,[142,65],163,[141,141],0,0,"a"],["f","median",["_"],"static",166,166,[166,48],170,[165,165],0,0,"a"]],"old":"","new":"//\n//  CaptureLens.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The camera-capture signature, computed: a square centre crop at native resolution (at most\n//        1024 px), its luma high-pass residual, the residual's power spectrum and radial profile;\n//        the profile's outer-half peak over its median is the Nyquist peak a Bayer mosaic leaves.\n//        Nine values for the camera head, four for the capture member, from one measurement.\n//  PIN:  Garde's captureCompute, unchanged (Python capture_signature.py): gray = 0.299R + 0.587G +\n//        0.114B in float (not cv2's uint8 gray), residual = gray − GaussianBlur(7, σ 1) reflect-101,\n//        mean removed; |fftshift(fft2)|²; numpy-bincount radial profile; peak = max(outer half) /\n//        (median + 1e-12); spectral flatness over prof[n/4…]; CFA trace over the 2×2 sub-grids;\n//        lag-1 correlation on every fifth pair. Aggregates in Double, host-side, for parity.\n//\n\nimport CoreGraphics\nimport Foundation\nimport MLX\nimport MLXAccelerate\nimport MLXFFT\n\npublic enum CaptureLens {\n    /// Both forms from one measurement: the nine values (zeros when the image cannot be measured)\n    /// and the signature (then valid by the native size alone, never present).\n    public static func reading(_ cgImage: CGImage) -> CaptureReading {\n        guard let features = compute(cgImage) else {\n            return CaptureReading(features: .zero, signature: CaptureSignature(\n                peak: 0, valid: cgImage.width >= CaptureLaw.minNativePixels && cgImage.height >= CaptureLaw.minNativePixels,\n                nativePixels: min(cgImage.width, cgImage.height), present: false))\n        }\n        return CaptureReading(features: features, signature: features.signature)\n    }\n\n    /// The nine values the camera head reads.\n    public static func features(_ cgImage: CGImage) -> CaptureFeatures { reading(cgImage).features }\n\n    /// The signature the capture member reports.\n    public static func signature(_ cgImage: CGImage) -> CaptureSignature { reading(cgImage).signature }\n\n    static func compute(_ cgImage: CGImage) -> CaptureFeatures? {\n        let W = cgImage.width, H = cgImage.height\n        let nativePx = min(W, H)\n        var win = min(min(W, H), CaptureLaw.analysisSide)\n        win -= win % 2\n        guard win >= 8 else { return nil }\n\n        let x0 = (W - win) / 2, y0 = (H - win) / 2\n        let bpp = 4\n        var px = [UInt8](repeating: 0, count: win * win * bpp)\n        guard let ctx = CGContext(data: &px, width: win, height: win, bitsPerComponent: 8, bytesPerRow: win * bpp,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else { return nil }\n        ctx.draw(cgImage, in: CGRect(x: -x0, y: -(H - win - y0), width: W, height: H))\n\n        var gray = [Float](repeating: 0, count: win * win)\n        for i in 0..<(win * win) {\n            let b = i * bpp\n            gray[i] = 0.299 * Float(px[b]) + 0.587 * Float(px[b + 1]) + 0.114 * Float(px[b + 2])\n        }\n\n        let g = MLXArray(gray, [win, win])\n        let blurred = batchedGaussianBlur(g.reshaped([1, win, win]), kernelSize: CaptureLaw.highPassKernel,\n                                          sigma: CaptureLaw.highPassSigma, border: .reflect101).reshaped([win, win])\n        var R = g - blurred\n        R = R - R.mean()\n        let spec = MLXFFT.fft2(R.asType(.float32))\n        let mag = MLXFFT.fftshift(MLX.abs(spec))\n        let power = mag * mag\n        MLX.eval(R, power)\n        let res = R.asArray(Float.self)\n        let P = power.asArray(Float.self)\n\n        let prof = radialProfile(P, h: win, w: win)\n        let n = prof.count\n        let hf = Array(prof[(n / 2)...])\n        let peak = hf.isEmpty ? 0 : Float(hf.max()! / (median(hf) + 1e-12))\n        let profSum = prof.reduce(0, +)\n        let hfRatio = Float(hf.reduce(0, +) / (profSum + 1e-12))\n        let band = Array(prof[(n / 4)...])\n        let geo = exp(band.reduce(0.0) { $0 + log($1 + 1e-12) } / Double(band.count))\n        let specFlat = Float(geo / (band.reduce(0, +) / Double(band.count) + 1e-12))\n\n        let resStd = stddev(res)\n        let cfaTrace = cfaSubgridTrace(res, win: win)\n        let acLag1 = lag1HorizCorr(res, win: win)\n\n        let valid: Float = nativePx >= CaptureLaw.minNativePixels ? 1 : 0\n        let present: Float = (valid > 0 && peak >= CaptureLaw.decisionPeak) ? 1 : 0\n        return CaptureFeatures(vector: [peak, valid, present, Float(nativePx), resStd, hfRatio, specFlat, cfaTrace, acLag1])\n    }\n\n    /// numpy: rr = sqrt((y−cy)² + (x−cx)²).astype(int); prof = bincount(rr, P) / max(bincount(rr), 1).\n    static func radialProfile(_ P: [Float], h: Int, w: Int) -> [Double] {\n        let cy = h / 2, cx = w / 2\n        let maxR = Int((Double(cy * cy + cx * cx)).squareRoot())\n        var sums = [Double](repeating: 0, count: maxR + 1)\n        var counts = [Int](repeating: 0, count: maxR + 1)\n        for i in 0..<h {\n            let dy2 = (i - cy) * (i - cy), rowBase = i * w\n            for j in 0..<w {\n                let dx = j - cx\n                let r = Int((Double(dy2 + dx * dx)).squareRoot())\n                sums[r] += Double(P[rowBase + j]); counts[r] += 1\n            }\n        }\n        return (0...maxR).map { sums[$0] / Double(max(counts[$0], 1)) }\n    }\n\n    /// Population std (numpy .std(), ddof 0).\n    static func stddev(_ a: [Float]) -> Float {\n        let n = Double(a.count)\n        guard n > 0 else { return 0 }\n        var m = 0.0\n        for v in a { m += Double(v) }\n        m /= n\n        var s = 0.0\n        for v in a { let d = Double(v) - m; s += d * d }\n        return Float((s / n).squareRoot())\n    }\n\n    /// (max − min) / mean of the four strided 2×2 sub-grid population variances.\n    static func cfaSubgridTrace(_ res: [Float], win: Int) -> Float {\n        var vars4 = [Double]()\n        vars4.reserveCapacity(4)\n        for a in 0..<2 {\n            for b in 0..<2 {\n                var m = 0.0, c = 0.0\n                var i = a\n                while i < win { var j = b; while j < win { m += Double(res[i * win + j]); c += 1; j += 2 }; i += 2 }\n                m /= max(c, 1)\n                var s = 0.0\n                i = a\n                while i < win { var j = b; while j < win { let d = Double(res[i * win + j]) - m; s += d * d; j += 2 }; i += 2 }\n                vars4.append(s / max(c, 1))\n            }\n        }\n        let mn = vars4.min()!, mx = vars4.max()!, mean = vars4.reduce(0, +) / 4.0\n        return Float((mx - mn) / (mean + 1e-9))\n    }\n\n    /// Pearson of res[:, :-1].ravel()[::5] against res[:, 1:].ravel()[::5].\n    static func lag1HorizCorr(_ res: [Float], win: Int) -> Float {\n        var xs = [Double](), ys = [Double]()\n        let total = win * (win - 1)\n        xs.reserveCapacity(total / 5 + 1); ys.reserveCapacity(total / 5 + 1)\n        var k = 0\n        for i in 0..<win {\n            let base = i * win\n            for j in 0..<(win - 1) {\n                if k % 5 == 0 { xs.append(Double(res[base + j])); ys.append(Double(res[base + j + 1])) }\n                k += 1\n            }\n        }\n        let n = Double(xs.count)\n        guard n > 1 else { return 0 }\n        var mx = 0.0, my = 0.0\n        for t in 0..<xs.count { mx += xs[t]; my += ys[t] }\n        mx /= n; my /= n\n        var sxy = 0.0, sxx = 0.0, syy = 0.0\n        for t in 0..<xs.count { let dx = xs[t] - mx, dy = ys[t] - my; sxy += dx * dy; sxx += dx * dx; syy += dy * dy }\n        let den = (sxx * syy).squareRoot()\n        return den > 1e-12 ? Float(sxy / den) : 0\n    }\n\n    /// numpy.median: the mean of the two middle elements for an even count.\n    static func median(_ a: [Double]) -> Double {\n        let s = a.sorted(), n = s.count\n        if n == 0 { return 0 }\n        return n % 2 == 1 ? s[n / 2] : (s[n / 2 - 1] + s[n / 2]) / 2.0\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Capture/ScreenshotLens.swift","status":"added","lang":"swift","hunks":[[1,0,1,78]],"header":{"lines":[1,10],"target":"VeilGardeLens","what":[6,8],"pin":[9,9],"in":null,"out":null,"style":"swift"},"marks":[],"first":319,"scopes":[["E","ScreenshotLens",null,"public",15,15,[15,27],78,null,-1,0,"a",[]],["f","gate",["_"],"public static",16,16,[16,66],77,null,0,0,"a"]],"old":"","new":"//\n//  ScreenshotLens.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The flat-UI gate's three tells, measured on the image capped at 2048 px: the share of\n//        interior pixels with no gradient, the share of perfectly flat 16-px blocks, and the share\n//        of the single most common colour.\n//  PIN:  Garde's screenshotGate, unchanged (host-side; Python capture_signature.py screenshot_gate).\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic enum ScreenshotLens {\n    public static func gate(_ cgImage: CGImage) -> ScreenshotGate {\n        let W = cgImage.width, H = cgImage.height\n        guard W >= 32, H >= 32 else { return .none }\n        var w = W, h = H\n        if max(W, H) > ScreenshotGate.cap {\n            let s = Double(ScreenshotGate.cap) / Double(max(W, H))\n            w = Int(Double(W) * s); h = Int(Double(H) * s)\n        }\n        let bpp = 4\n        var px = [UInt8](repeating: 0, count: w * h * bpp)\n        guard let ctx = CGContext(data: &px, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * bpp,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else { return .none }\n        ctx.draw(cgImage, in: CGRect(x: 0, y: 0, width: w, height: h))\n\n        var gray = [Float](repeating: 0, count: w * h)\n        var hist = [UInt32: Int]()\n        hist.reserveCapacity(4096)\n        var topCount = 0\n        for i in 0..<(w * h) {\n            let b = i * bpp\n            let r = px[b], gg = px[b + 1], bl = px[b + 2]\n            gray[i] = 0.299 * Float(r) + 0.587 * Float(gg) + 0.114 * Float(bl)\n            let code = (UInt32(r) << 16) | (UInt32(gg) << 8) | UInt32(bl)\n            let c = (hist[code] ?? 0) + 1\n            hist[code] = c\n            if c > topCount { topCount = c }\n        }\n        let topColor = Float(topCount) / Float(w * h)\n\n        // grad_zero: interior pixels with |Sobel_x| + |Sobel_y| < 1e-3.\n        var flatPx = 0\n        for y in 1..<(h - 1) {\n            let r0 = (y - 1) * w, r1 = y * w, r2 = (y + 1) * w\n            for x in 1..<(w - 1) {\n                let gx = -gray[r0 + x - 1] + gray[r0 + x + 1] - 2 * gray[r1 + x - 1] + 2 * gray[r1 + x + 1] - gray[r2 + x - 1] + gray[r2 + x + 1]\n                let gy = -gray[r0 + x - 1] - 2 * gray[r0 + x] - gray[r0 + x + 1] + gray[r2 + x - 1] + 2 * gray[r2 + x] + gray[r2 + x + 1]\n                if abs(gx) + abs(gy) < 1e-3 { flatPx += 1 }\n            }\n        }\n        let gradZero = Float(flatPx) / Float(w * h)\n\n        // flat_strict: 16×16 blocks with population std < 0.3.\n        let bs = 16\n        var blocks = 0, flatBlocks = 0\n        var y = 0\n        while y + bs <= h {\n            var x = 0\n            while x + bs <= w {\n                var m: Float = 0\n                for j in 0..<bs { let row = (y + j) * w + x; for k in 0..<bs { m += gray[row + k] } }\n                m /= Float(bs * bs)\n                var s: Float = 0\n                for j in 0..<bs { let row = (y + j) * w + x; for k in 0..<bs { let d = gray[row + k] - m; s += d * d } }\n                if (s / Float(bs * bs)).squareRoot() < 0.3 { flatBlocks += 1 }\n                blocks += 1\n                x += bs\n            }\n            y += bs\n        }\n        let flatStrict = blocks > 0 ? Float(flatBlocks) / Float(blocks) : 0\n        return ScreenshotGate.decide(gradZero: gradZero, flatStrict: flatStrict, topColor: topColor)\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Image/ImageCodec.swift","status":"added","lang":"swift","hunks":[[1,0,1,88]],"header":{"lines":[1,21],"target":"VeilGardeLens","what":[6,10],"pin":[11,20],"in":null,"out":null,"style":"swift"},"marks":[],"first":321,"scopes":[["E","ImageCodec",null,"public",29,29,[29,23],88,null,-1,0,"a",[]],["E","Format",null,"public",30,30,[30,64],34,null,0,0,"a",["jpeg","heic"]],["v","identifier",null,"",33,33,[33,31],33,null,1,8,"a"],["f","flattened",["_"],"public static",38,38,[38,60],44,[36,37],0,0,"a"],["f","isFlat",["_"],"public static",47,47,[47,53],50,[46,46],0,0,"a"],["f","canEncode",["_"],"public static",53,53,[53,59],55,[52,52],0,0,"a"],["f","encode",["_","as","quality"],"public static",58,58,[58,96],67,[57,57],0,0,"a"],["f","recompressed",["_","as","quality"],"public static",70,70,[70,105],72,[69,69],0,0,"a"],["f","resized",["_","width","height"],"public static",75,75,[75,83],82,[74,74],0,0,"a"],["f","resized",["_","by"],"public static",85,85,[85,77],87,[84,84],0,0,"a"]],"old":"","new":"//\n//  ImageCodec.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: An image recompressed in memory, the way a platform recompresses an upload: encoded as\n//        JPEG or HEIC at a quality through ImageIO and decoded back the way every image here is\n//        decoded, and an image resized through CoreGraphics; first of all, an image flattened to\n//        the 8-bit device-RGB bitmap every lens reads. The watermark's acceptance run is built\n//        on it.\n//  PIN:  ImageIO's quality scale is its own: 0.75 here is not libjpeg's q75, which is what the\n//        cv2 recipes meant. macOS ImageIO has no WebP encoder, so HEIC stands in wherever the\n//        recipes call for WebP, and the stand-in is named wherever it is used. The resize draws\n//        with high-quality interpolation into 8-bit device RGB (cv2's INTER_AREA has no\n//        CoreGraphics twin). Encoding always starts from the flattened bitmap: an iPhone photo\n//        decodes to 10 bits per channel, and on 2026-10-19 one such 24.5 MP image, encoded long\n//        after its decode in a process that had run MLX for minutes, sat in\n//        CGImageDestinationFinalize for over five minutes while the GPU was saturated (in a fresh\n//        process the same encode takes 0.48 s). Flattened, it encodes in 0.06 s, and the lens reads\n//        the same pixels either way, since it draws into the same bitmap. Nothing touches the disk.\n//\n\nimport CoreGraphics\nimport Foundation\nimport ImageIO\nimport UniformTypeIdentifiers\nimport VeilGardeCore\n\npublic enum ImageCodec {\n    public enum Format: String, Sendable, Codable, CaseIterable {\n        case jpeg, heic\n\n        var identifier: String { (self == .jpeg ? UTType.jpeg : UTType.heic).identifier }\n    }\n\n    /// `cg` drawn into an 8-bit device-RGB bitmap with no alpha: exactly the pixels\n    /// ImageLoading.rgbPixels reads, so flattening first changes nothing a lens measures.\n    public static func flattened(_ cg: CGImage) -> CGImage? {\n        if isFlat(cg) { return cg }\n        guard let ctx = CGContext(data: nil, width: cg.width, height: cg.height, bitsPerComponent: 8, bytesPerRow: 0,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else { return nil }\n        ctx.draw(cg, in: CGRect(x: 0, y: 0, width: cg.width, height: cg.height))\n        return ctx.makeImage()\n    }\n\n    /// Already an 8-bit device-RGB bitmap without alpha.\n    public static func isFlat(_ cg: CGImage) -> Bool {\n        cg.bitsPerComponent == 8 && cg.bitsPerPixel == 32 && cg.alphaInfo == .noneSkipLast\n            && cg.colorSpace.map { CFEqual($0, CGColorSpaceCreateDeviceRGB()) } == true\n    }\n\n    /// Whether this Mac's ImageIO can write `format`.\n    public static func canEncode(_ format: Format) -> Bool {\n        ((CGImageDestinationCopyTypeIdentifiers() as? [String]) ?? []).contains(format.identifier)\n    }\n\n    /// `cg`, flattened, encoded as `format` at `quality` in 0…1.\n    public static func encode(_ cg: CGImage, as format: Format, quality: Double) throws -> Data {\n        guard let flat = flattened(cg) else { throw VeilGardeFailure.internalError(\"cannot flatten a \\(cg.width)×\\(cg.height) image\") }\n        let out = NSMutableData()\n        guard let destination = CGImageDestinationCreateWithData(out, format.identifier as CFString, 1, nil) else {\n            throw VeilGardeFailure.internalError(\"ImageIO has no \\(format.rawValue) encoder on this Mac\")\n        }\n        CGImageDestinationAddImage(destination, flat, [kCGImageDestinationLossyCompressionQuality: quality] as CFDictionary)\n        guard CGImageDestinationFinalize(destination) else { throw VeilGardeFailure.internalError(\"the \\(format.rawValue) encode failed\") }\n        return out as Data\n    }\n\n    /// `cg` after a round trip through `format` at `quality`.\n    public static func recompressed(_ cg: CGImage, as format: Format, quality: Double) throws -> CGImage {\n        try ImageDecoding.cgImage(data: try encode(cg, as: format, quality: quality), name: \"a \\(format.rawValue) re-encode\")\n    }\n\n    /// `cg` drawn at `width` × `height`.\n    public static func resized(_ cg: CGImage, width: Int, height: Int) -> CGImage? {\n        let w = max(1, width), h = max(1, height)\n        guard let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0, space: CGColorSpaceCreateDeviceRGB(),\n                                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }\n        ctx.interpolationQuality = .high\n        ctx.draw(cg, in: CGRect(x: 0, y: 0, width: w, height: h))\n        return ctx.makeImage()\n    }\n\n    /// `cg` scaled by `factor`, each side rounded.\n    public static func resized(_ cg: CGImage, by factor: Double) -> CGImage? {\n        resized(cg, width: Int((Double(cg.width) * factor).rounded()), height: Int((Double(cg.height) * factor).rounded()))\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Image/ImageDecoding.swift","status":"added","lang":"swift","hunks":[[1,0,1,47]],"header":{"lines":[1,17],"target":"VeilGardeLens","what":[6,8],"pin":[9,16],"in":null,"out":null,"style":"swift"},"marks":[],"first":331,"scopes":[["E","ImageDecoding",null,"public",24,24,[24,26],47,null,-1,0,"a",[]],["f","cgImage",["contentsOf"],"public static",25,25,[25,70],31,null,0,0,"a"],["f","cgImage",["data","name"],"public static",33,33,[33,85],39,null,0,0,"a"],["f","orientation",["of"],"public static",42,42,[42,55],46,[41,41],0,0,"a"]],"old":"","new":"//\n//  ImageDecoding.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Bytes to a CGImage, the way every shipped artifact has seen them: through NSImage, which\n//        applies the EXIF orientation (an iPhone photo stored sideways is analysed upright) and,\n//        for some sources, re-renders the rotated image in its own colour space.\n//  PIN:  Garde loaded every image as NSImage(contentsOf:).cgImage(forProposedRect: nil, …), and\n//        the heads and the fusion corpus were computed from Swift features decoded that way.\n//        Measured 2026-10-19 against Garde's own runs:\n//        on unrotated images NSImage and ImageIO agree byte for byte, but on rotated iPhone JPEGs\n//        NSImage renders Display P3 into Generic RGB (bitmap info 8194) and a pixel-exact ImageIO\n//        rotation differs by up to 58 levels, moving the capture peak by up to 50 and flipping a\n//        verdict. So decoding stays NSImage's, the only AppKit use in Sources\n//        (PackageLayeringTests). ImageIO is the fallback only for bytes NSImage cannot read.\n//\n\nimport AppKit\nimport CoreGraphics\nimport Foundation\nimport ImageIO\n\npublic enum ImageDecoding {\n    public static func cgImage(contentsOf url: URL) throws -> CGImage {\n        if let image = NSImage(contentsOf: url), let cg = image.cgImage(forProposedRect: nil, context: nil, hints: nil) { return cg }\n        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil), let cg = CGImageSourceCreateImageAtIndex(source, 0, nil) else {\n            throw VeilGardeFailure.data(\"cannot decode an image from \\(url.path)\")\n        }\n        return cg\n    }\n\n    public static func cgImage(data: Data, name: String = \"image\") throws -> CGImage {\n        if let image = NSImage(data: data), let cg = image.cgImage(forProposedRect: nil, context: nil, hints: nil) { return cg }\n        guard let source = CGImageSourceCreateWithData(data as CFData, nil), let cg = CGImageSourceCreateImageAtIndex(source, 0, nil) else {\n            throw VeilGardeFailure.data(\"cannot decode \\(name) as an image\")\n        }\n        return cg\n    }\n\n    /// The EXIF orientation of the first frame (1 when absent), for reports.\n    public static func orientation(of url: URL) -> Int {\n        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return 1 }\n        let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any] ?? [:]\n        return (properties[kCGImagePropertyOrientation] as? NSNumber)?.intValue ?? 1\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Image/ImageLoading.swift","status":"added","lang":"swift","hunks":[[1,0,1,50]],"header":{"lines":[1,12],"target":"VeilGardeLens","what":[6,7],"pin":[8,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":335,"scopes":[["E","ImageLoading",null,"public",17,17,[17,25],50,null,-1,0,"a",[]],["f","rgbPixels",["_","width","height"],"public static",19,19,[19,100],37,[18,18],0,0,"a"],["f","renderCrop",["_","_"],"public static",40,40,[40,80],49,[39,39],0,0,"a"]],"old":"","new":"//\n//  ImageLoading.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A CGImage to an RGB float plane (0–255, the given size, top row first), and crops\n//        rendered as fresh standalone bitmaps.\n//  PIN:  The plane is drawn into an RGBA noneSkipLast context with CoreGraphics' default\n//        interpolation. renderCrop, never cropping(to:): cropping returns a view with the parent's\n//        stride that raw-byte extractors misread (measured 2026-07: one interior scored 0.807 as a\n//        bitmap and 0.001 as a view).\n//\n\nimport CoreGraphics\nimport Foundation\n\npublic enum ImageLoading {\n    /// The RGB bytes of `cgImage` drawn at w × h, top row first, as floats.\n    public static func rgbPixels(_ cgImage: CGImage, width w: Int, height h: Int) throws -> [Float] {\n        let bytesPerPixel = 4\n        var pixelData = [UInt8](repeating: 0, count: w * h * bytesPerPixel)\n        guard let ctx = CGContext(data: &pixelData, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * bytesPerPixel,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else {\n            throw VeilGardeFailure.internalError(\"cannot create a \\(w)×\\(h) CGContext\")\n        }\n        ctx.draw(cgImage, in: CGRect(x: 0, y: 0, width: w, height: h))\n        var real = [Float](repeating: 0, count: h * w * 3)\n        for i in 0..<h {\n            for j in 0..<w {\n                let base = (i * w + j) * bytesPerPixel\n                real[(i * w + j) * 3 + 0] = Float(pixelData[base + 0])\n                real[(i * w + j) * 3 + 1] = Float(pixelData[base + 1])\n                real[(i * w + j) * 3 + 2] = Float(pixelData[base + 2])\n            }\n        }\n        return real\n    }\n\n    /// A crop rendered into a fresh standalone bitmap. `rect` is in image coordinates, origin top-left.\n    public static func renderCrop(_ image: CGImage, _ rect: CGRect) -> CGImage? {\n        let w = Int(rect.width), h = Int(rect.height)\n        guard w > 32, h > 32,\n              let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0, space: CGColorSpaceCreateDeviceRGB(),\n                                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }\n        ctx.interpolationQuality = .none\n        let dy = CGFloat(image.height) - rect.maxY\n        ctx.draw(image, in: CGRect(x: -rect.minX, y: -dy, width: CGFloat(image.width), height: CGFloat(image.height)))\n        return ctx.makeImage()\n    }\n}\n"},{"path":"Sources/VeilGardeLens/LensRuntime.swift","status":"added","lang":"swift","hunks":[[1,0,1,32]],"header":{"lines":[1,10],"target":"VeilGardeLens","what":[6,7],"pin":[8,9],"in":null,"out":null,"style":"swift"},"marks":[],"first":338,"scopes":[["E","LensRuntime",null,"public",15,15,[15,24],32,null,-1,0,"a",[]],["f","deviceName",["cpu"],"public static",17,17,[17,55],17,[16,16],0,8,"a"],["v","defaultDeviceDescription",null,"public static",19,19,[19,55],19,null,0,8,"a"],["f","withDevice",["cpu","_"],"public static",22,22,[22,86],24,[21,21],0,0,"a"],["f","configureGPUMemory",["cacheLimitBytes","memoryLimitBytes"],"public static",26,26,[26,113],29,null,0,0,"a"],["f","releaseMemory",[],"public static",31,31,[31,39],31,null,0,8,"a"]],"old":"","new":"//\n//  LensRuntime.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX runtime controls the layers above need without importing MLX: the default device,\n//        a CPU run for A/B checks, the GPU buffer-cache bounds, and releasing cached buffers.\n//  PIN:  One MLX workload at a time. The cache bounds mirror the reference app's GPU-memory\n//        settings: a sequence of inferences must not grow the Metal working set without bound.\n//\n\nimport Foundation\nimport MLX\n\npublic enum LensRuntime {\n    /// \"gpu\" or \"cpu\", as the result JSON's `device` field spells it.\n    public static func deviceName(cpu: Bool) -> String { cpu ? \"cpu\" : \"gpu\" }\n\n    public static var defaultDeviceDescription: String { \"\\(Device.defaultDevice())\" }\n\n    /// Runs `body` with MLX's default device set to the CPU or the GPU.\n    public static func withDevice<T>(cpu: Bool, _ body: () throws -> T) rethrows -> T {\n        try Device.withDefaultDevice(cpu ? Device(.cpu) : Device(.gpu), body)\n    }\n\n    public static func configureGPUMemory(cacheLimitBytes: Int = 64 * 1024 * 1024, memoryLimitBytes: Int? = nil) {\n        Memory.cacheLimit = cacheLimitBytes\n        if let m = memoryLimitBytes { Memory.memoryLimit = m }\n    }\n\n    public static func releaseMemory() { Memory.clearCache() }\n}\n"},{"path":"Sources/VeilGardeLens/Scoring/TreeModelCache.swift","status":"added","lang":"swift","hunks":[[1,0,1,45]],"header":{"lines":[1,10],"target":"VeilGardeLens","what":[6,7],"pin":[8,9],"in":null,"out":null,"style":"swift"},"marks":[],"first":344,"scopes":[["C","TreeModelCache",null,"public final",18,18,[18,55],33,[15,17],-1,0,"a"],["f","model",["_"],"public",23,23,[23,61],32,null,0,0,"a"],["S","FileStamp",null,"public",36,36,[36,45],45,[35,35],-1,0,"a"],["i","init",["path"],"public",40,40,[40,30],44,null,2,0,"a"]],"old":"","new":"//\n//  TreeModelCache.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Frigate's XGBoostTreeModel, the evaluator the detector scores the camera head with, parsed\n//        once per file and shared.\n//  PIN:  The only file in the Lens that imports the Frigate umbrella, for FrigateBoost's evaluator;\n//        Core's GBDTModel agrees with it bit for bit on the shipped camera head (ScorerTests).\n//\n\nimport Foundation\nimport Frigate\n\n/// Parsed XGBoost models by path, read-only and shared, so a run of inferences never re-parses\n/// a model. An entry is keyed by the file's path, modification date and size, so a model the\n/// flywheel rewrites in place (a promote, a restore) is parsed again in the same process.\npublic final class TreeModelCache: @unchecked Sendable {\n    public static let shared = TreeModelCache()\n    private let lock = NSLock()\n    private var cache: [String: (stamp: FileStamp, model: XGBoostTreeModel)] = [:]\n\n    public func model(_ url: URL) throws -> XGBoostTreeModel {\n        let key = url.standardizedFileURL.path\n        let stamp = FileStamp(path: key)\n        lock.lock()\n        if let hit = cache[key], hit.stamp == stamp { lock.unlock(); return hit.model }\n        lock.unlock()\n        let m = try XGBoostTreeModel(url: url)\n        lock.lock(); cache[key] = (stamp, m); lock.unlock()\n        return m\n    }\n}\n\n/// A file's modification date and size: what a cache compares to know a file was rewritten.\npublic struct FileStamp: Equatable, Sendable {\n    public let modified: Date?\n    public let size: Int?\n\n    public init(path: String) {\n        let attributes = try? FileManager.default.attributesOfItem(atPath: path)\n        modified = attributes?[.modificationDate] as? Date\n        size = (attributes?[.size] as? NSNumber)?.intValue\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Scoring/WeightLocator.swift","status":"added","lang":"swift","hunks":[[1,0,1,79]],"header":{"lines":[1,11],"target":"VeilGardeLens","what":[6,8],"pin":[9,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":348,"scopes":[["E","WeightFile",null,"public",15,15,[15,55],29,null,-1,0,"a",["dinov2Small","dinov2XSmall","dinov2XXSmall","clipVision"]],["v","role",null,"public",21,21,[21,34],28,null,0,0,"a"],["C","WeightLocator",null,"public final",31,31,[31,54],79,null,-1,0,"a"],["f","setOverride",["_"],"public",40,40,[40,47],42,[39,39],2,0,"a"],["f","register",["_"],"public",45,45,[45,43],49,[44,44],2,0,"a"],["f","searchPath",[],"public",52,52,[52,38],61,[51,51],2,0,"a"],["f","url",["_"],"public",63,63,[63,48],63,null,2,8,"a"],["f","url",["named"],"public",65,65,[65,48],71,null,2,0,"a"],["f","require",["_"],"public",74,74,[74,58],78,[73,73],2,0,"a"]],"old":"","new":"//\n//  WeightLocator.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Where the neural weights are found. None ships in git, so each is looked up by file name:\n//        an override folder a host sets, then VEILGARDE_WEIGHTS, then the folders registered at\n//        start-up (the work area's weights/ and the shipped bundle's resources).\n//  PIN:  The reference's weight-override contract, generalized to an ordered search. The first folder\n//        that holds the file wins; nothing is downloaded here (`veilgarde weights` does that).\n//\n\nimport Foundation\n\npublic enum WeightFile: String, CaseIterable, Sendable {\n    case dinov2Small = \"dinov2_small.safetensors\"\n    case dinov2XSmall = \"dinov2_small_xsmall.safetensors\"\n    case dinov2XXSmall = \"dinov2_small_xxsmall.safetensors\"\n    case clipVision = \"clip_vit_b32_vision.safetensors\"\n\n    public var role: ArtifactRole {\n        switch self {\n        case .dinov2Small: return .dinov2Small\n        case .dinov2XSmall: return .dinov2XSmall\n        case .dinov2XXSmall: return .dinov2XXSmall\n        case .clipVision: return .clipVision\n        }\n    }\n}\n\npublic final class WeightLocator: @unchecked Sendable {\n    public static let shared = WeightLocator()\n    public static let environmentKey = \"VEILGARDE_WEIGHTS\"\n\n    private let lock = NSLock()\n    private var override: URL?\n    private var registered: [URL] = []\n\n    /// A folder searched before every other (a host app's own copy, `--weights-dir`).\n    public func setOverride(_ directory: URL?) {\n        lock.lock(); override = directory; lock.unlock()\n    }\n\n    /// A folder searched after the override and the environment, once.\n    public func register(_ directory: URL) {\n        lock.lock()\n        if !registered.contains(directory.standardizedFileURL) { registered.append(directory.standardizedFileURL) }\n        lock.unlock()\n    }\n\n    /// Every folder searched, in order.\n    public func searchPath() -> [URL] {\n        lock.lock()\n        defer { lock.unlock() }\n        var path: [URL] = []\n        if let override { path.append(override) }\n        if let env = ProcessInfo.processInfo.environment[Self.environmentKey], !env.isEmpty {\n            path.append(URL(fileURLWithPath: (env as NSString).expandingTildeInPath, isDirectory: true))\n        }\n        return path + registered\n    }\n\n    public func url(_ file: WeightFile) -> URL? { url(named: file.rawValue) }\n\n    public func url(named name: String) -> URL? {\n        for directory in searchPath() {\n            let candidate = directory.appendingPathComponent(name)\n            if FileManager.default.fileExists(atPath: candidate.path) { return candidate }\n        }\n        return nil\n    }\n\n    /// The weight file, or a failure naming where it was looked for.\n    public func require(_ file: WeightFile) throws -> URL {\n        if let url = url(file) { return url }\n        throw VeilGardeFailure.missing(\"no \\(file.rawValue) in \\(searchPath().map(\\.path).joined(separator: \", \"))\",\n                                       hint: \"put the weights in the work area's weights/ (`veilgarde weights import-dinov2` builds DINOv2's), or pass --weights-dir\")\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Semantic/CLIPVision.swift","status":"added","lang":"swift","hunks":[[1,0,1,199]],"header":{"lines":[1,15],"target":"VeilGardeLens","what":[6,8],"pin":[9,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":357,"scopes":[["C","CLIPAttention",null,"final",22,22,[22,34],47,null,-1,0,"a"],["i","init",["dims","heads"],"",30,30,[30,32],37,null,0,0,"a"],["f","callAsFunction",["_"],"",39,39,[39,51],46,null,0,0,"a"],["C","CLIPMLP",null,"final",49,49,[49,28],62,null,-1,0,"a"],["i","init",["dims","hidden"],"",53,53,[53,33],56,null,3,0,"a"],["f","callAsFunction",["_"],"",58,58,[58,51],61,null,3,0,"a"],["C","CLIPEncoderLayer",null,"final",64,64,[64,37],81,null,-1,0,"a"],["i","init",["dims","heads","hidden","eps"],"",70,70,[70,57],75,null,6,0,"a"],["f","callAsFunction",["_"],"",77,77,[77,51],80,null,6,0,"a"],["C","CLIPEncoder",null,"final",83,83,[83,32],89,null,-1,0,"a"],["i","init",["count","dims","heads","hidden","eps"],"",86,86,[86,69],88,null,9,0,"a"],["C","CLIPEmbeddings",null,"final",91,91,[91,35],101,null,-1,0,"a"],["i","init",["dims","patch","positions"],"",96,96,[96,48],100,null,11,0,"a"],["C","CLIPVision",null,"public final",103,103,[103,38],142,null,-1,0,"a"],["i","init",["dims","layers","heads","hidden","patch","projectionDims","eps"],"public",113,113,[113,151],121,null,13,0,"a"],["f","callAsFunction",["_"],"public",124,124,[124,63],135,[123,123],13,0,"a"],["f","loadWeights",["url"],"public",137,137,[137,45],141,null,13,0,"a"],["E","CLIPPreprocess",null,"public",146,146,[146,27],177,[144,145],-1,0,"a",[]],["f","crop",["_","size"],"public static",151,151,[151,88],164,[150,150],17,0,"a"],["f","input",["pixels","count","size"],"public static",167,167,[167,106],174,[166,166],17,0,"a"],["f","input",["_"],"public static",176,176,[176,56],176,null,17,8,"a"],["C","CLIPLens",null,"public final",180,180,[180,49],199,[179,179],-1,0,"a"],["f","tower",[],"public",185,185,[185,45],193,null,21,0,"a"],["f","embedding",["_"],"public static",196,196,[196,66],198,[195,195],21,0,"a"]],"old":"","new":"//\n//  CLIPVision.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: CLIP ViT-B/32's vision tower and its projection in MLXNN: an image to the 512-value,\n//        L2-normalized embedding the flywheel's category router compares with its prompt matrix\n//        (what an acquired generated image depicts: a person, a scene, a blur, a render, art).\n//  PIN:  openai/clip-vit-base-patch32 as Hugging Face's CLIPVisionModel runs it: a 32-px patch\n//        Conv2d without bias (7×7 = 49 patches) plus a class token and 50 learned positions,\n//        pre-LayerNorm (\"pre_layrnorm\", HF's spelling), 12 layers of 12-head attention and a\n//        3072-wide MLP with quick-GELU (x·σ(1.702x)), LayerNorm ε 1e-5, the class token's\n//        post-LayerNorm projected 768 → 512 without bias. Keys are HF's minus \"vision_model.\";\n//        the patch kernel is stored [O, kH, kW, I] (`veilgarde weights import-clip`).\n//\n\nimport CoreGraphics\nimport Foundation\nimport MLX\nimport MLXNN\n\nfinal class CLIPAttention: Module {\n    let heads: Int\n    let scale: Float\n    @ModuleInfo(key: \"q_proj\") var q: Linear\n    @ModuleInfo(key: \"k_proj\") var k: Linear\n    @ModuleInfo(key: \"v_proj\") var v: Linear\n    @ModuleInfo(key: \"out_proj\") var out: Linear\n\n    init(dims: Int, heads: Int) {\n        self.heads = heads\n        self.scale = pow(Float(dims / heads), -0.5)\n        self._q.wrappedValue = Linear(dims, dims, bias: true)\n        self._k.wrappedValue = Linear(dims, dims, bias: true)\n        self._v.wrappedValue = Linear(dims, dims, bias: true)\n        self._out.wrappedValue = Linear(dims, dims, bias: true)\n    }\n\n    func callAsFunction(_ x: MLXArray) -> MLXArray {\n        let (B, L) = (x.dim(0), x.dim(1))\n        let qa = (q(x) * scale).reshaped(B, L, heads, -1).transposed(0, 2, 1, 3)\n        let ka = k(x).reshaped(B, L, heads, -1).transposed(0, 2, 1, 3)\n        let va = v(x).reshaped(B, L, heads, -1).transposed(0, 2, 1, 3)\n        let weights = softmax(matmul(qa, ka.transposed(0, 1, 3, 2)), axis: -1)\n        return out(matmul(weights, va).transposed(0, 2, 1, 3).reshaped(B, L, -1))\n    }\n}\n\nfinal class CLIPMLP: Module {\n    @ModuleInfo(key: \"fc1\") var fc1: Linear\n    @ModuleInfo(key: \"fc2\") var fc2: Linear\n\n    init(dims: Int, hidden: Int) {\n        self._fc1.wrappedValue = Linear(dims, hidden, bias: true)\n        self._fc2.wrappedValue = Linear(hidden, dims, bias: true)\n    }\n\n    func callAsFunction(_ x: MLXArray) -> MLXArray {\n        let h = fc1(x)\n        return fc2(h * sigmoid(1.702 * h))\n    }\n}\n\nfinal class CLIPEncoderLayer: Module {\n    @ModuleInfo(key: \"self_attn\") var attention: CLIPAttention\n    @ModuleInfo(key: \"layer_norm1\") var norm1: LayerNorm\n    @ModuleInfo(key: \"mlp\") var mlp: CLIPMLP\n    @ModuleInfo(key: \"layer_norm2\") var norm2: LayerNorm\n\n    init(dims: Int, heads: Int, hidden: Int, eps: Float) {\n        self._attention.wrappedValue = CLIPAttention(dims: dims, heads: heads)\n        self._norm1.wrappedValue = LayerNorm(dimensions: dims, eps: eps)\n        self._mlp.wrappedValue = CLIPMLP(dims: dims, hidden: hidden)\n        self._norm2.wrappedValue = LayerNorm(dimensions: dims, eps: eps)\n    }\n\n    func callAsFunction(_ x: MLXArray) -> MLXArray {\n        let h = x + attention(norm1(x))\n        return h + mlp(norm2(h))\n    }\n}\n\nfinal class CLIPEncoder: Module {\n    let layers: [CLIPEncoderLayer]\n\n    init(count: Int, dims: Int, heads: Int, hidden: Int, eps: Float) {\n        self.layers = (0..<count).map { _ in CLIPEncoderLayer(dims: dims, heads: heads, hidden: hidden, eps: eps) }\n    }\n}\n\nfinal class CLIPEmbeddings: Module {\n    @ModuleInfo(key: \"patch_embedding\") var patch: Conv2d\n    @ParameterInfo(key: \"class_embedding\") var classEmbedding: MLXArray\n    @ModuleInfo(key: \"position_embedding\") var position: Embedding\n\n    init(dims: Int, patch: Int, positions: Int) {\n        self._patch.wrappedValue = Conv2d(inputChannels: 3, outputChannels: dims, kernelSize: .init(patch), stride: .init(patch), bias: false)\n        self._classEmbedding.wrappedValue = MLXArray.zeros([dims])\n        self._position.wrappedValue = Embedding(embeddingCount: positions, dimensions: dims)\n    }\n}\n\npublic final class CLIPVision: Module {\n    public static let embeddingWidth = 512\n    public static let inputSize = 224\n\n    @ModuleInfo(key: \"embeddings\") var embeddings: CLIPEmbeddings\n    @ModuleInfo(key: \"pre_layrnorm\") var preNorm: LayerNorm\n    @ModuleInfo(key: \"encoder\") var encoder: CLIPEncoder\n    @ModuleInfo(key: \"post_layernorm\") var postNorm: LayerNorm\n    @ModuleInfo(key: \"visual_projection\") var projection: Linear\n\n    public init(dims: Int = 768, layers: Int = 12, heads: Int = 12, hidden: Int = 3072, patch: Int = 32, projectionDims: Int = 512, eps: Float = 1e-5) {\n        let grid = Self.inputSize / patch\n        self._embeddings.wrappedValue = CLIPEmbeddings(dims: dims, patch: patch, positions: grid * grid + 1)\n        self._preNorm.wrappedValue = LayerNorm(dimensions: dims, eps: eps)\n        self._encoder.wrappedValue = CLIPEncoder(count: layers, dims: dims, heads: heads, hidden: hidden, eps: eps)\n        self._postNorm.wrappedValue = LayerNorm(dimensions: dims, eps: eps)\n        self._projection.wrappedValue = Linear(dims, projectionDims, bias: false)\n        super.init()\n    }\n\n    /// The L2-normalized image embeddings (B, 512), F32, for NHWC CLIP-normalized pixels.\n    public func callAsFunction(_ pixels: MLXArray) -> MLXArray {\n        let B = pixels.dim(0)\n        var p = embeddings.patch(pixels.asType(.float32))\n        p = p.flattened(start: 1, end: 2)\n        let cls = broadcast(embeddings.classEmbedding.reshaped(1, 1, -1), to: [B, 1, p.dim(2)])\n        var x = concatenated([cls, p], axis: 1) + embeddings.position.weight.expandedDimensions(axis: 0)\n        x = preNorm(x)\n        for layer in encoder.layers { x = layer(x) }\n        let pooled = postNorm(x[0..., 0, 0...])\n        let e = projection(pooled)\n        return e / sqrt((e * e).sum(axis: -1, keepDims: true))\n    }\n\n    public func loadWeights(url: URL) throws {\n        let w = try loadArrays(url: url)\n        try update(parameters: ModuleParameters.unflattened(w), verify: [.all])\n        eval(self)\n    }\n}\n\n/// CLIPImageProcessor's input, the way the DINOv2 port draws its own: shortest side to 224 with\n/// CoreGraphics' high-quality interpolation, centre crop 224, /255, CLIP's mean and std.\npublic enum CLIPPreprocess {\n    public static let mean: [Float] = [0.48145466, 0.4578275, 0.40821073]\n    public static let std: [Float] = [0.26862954, 0.26130258, 0.27577711]\n\n    /// The resized, centre-cropped RGB bytes, row 0 the top, [224 · 224 · 3].\n    public static func crop(_ cg: CGImage, size: Int = CLIPVision.inputSize) -> [UInt8] {\n        let scale = Double(size) / Double(min(cg.width, cg.height))\n        let sw = Double(cg.width) * scale, sh = Double(cg.height) * scale\n        var rgba = [UInt8](repeating: 0, count: size * size * 4)\n        guard let ctx = CGContext(data: &rgba, width: size, height: size, bitsPerComponent: 8, bytesPerRow: size * 4,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else {\n            return [UInt8](repeating: 0, count: size * size * 3)\n        }\n        ctx.interpolationQuality = .high\n        ctx.draw(cg, in: CGRect(x: -(sw - Double(size)) / 2, y: -(sh - Double(size)) / 2, width: sw, height: sh))\n        var rgb = [UInt8](repeating: 0, count: size * size * 3)\n        for i in 0..<(size * size) { rgb[i * 3] = rgba[i * 4]; rgb[i * 3 + 1] = rgba[i * 4 + 1]; rgb[i * 3 + 2] = rgba[i * 4 + 2] }\n        return rgb\n    }\n\n    /// RGB bytes [n · 224 · 224 · 3] to the tower's (n, 224, 224, 3) input.\n    public static func input(pixels: [UInt8], count n: Int, size: Int = CLIPVision.inputSize) -> MLXArray {\n        var floats = [Float](repeating: 0, count: pixels.count)\n        for i in 0..<pixels.count {\n            let c = i % 3\n            floats[i] = (Float(pixels[i]) / 255 - mean[c]) / std[c]\n        }\n        return MLXArray(floats, [n, size, size, 3])\n    }\n\n    public static func input(_ cg: CGImage) -> MLXArray { input(pixels: crop(cg), count: 1) }\n}\n\n/// The tower, loaded once from WeightLocator's clip_vit_b32_vision.safetensors.\npublic final class CLIPLens: @unchecked Sendable {\n    public static let shared = CLIPLens()\n    private let lock = NSLock()\n    private var model: CLIPVision?\n\n    public func tower() throws -> CLIPVision {\n        lock.lock()\n        defer { lock.unlock() }\n        if let model { return model }\n        let m = CLIPVision()\n        try m.loadWeights(url: WeightLocator.shared.require(.clipVision))\n        model = m\n        return m\n    }\n\n    /// The image's 512-value normalized embedding.\n    public static func embedding(_ cg: CGImage) throws -> [Float] {\n        try shared.tower()(CLIPPreprocess.input(cg)).reshaped(-1).asArray(Float.self)\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Semantic/DinoVariant.swift","status":"added","lang":"swift","hunks":[[1,0,1,25]],"header":{"lines":[1,9],"target":"VeilGardeLens","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":381,"scopes":[["E","DinoVariant",null,"public",11,11,[11,65],25,null,-1,0,"a",["small","xsmall","xxsmall"]],["v","weightFile",null,"public",14,14,[14,38],20,null,0,0,"a"],["v","isQuantized",null,"public",22,22,[22,33],22,null,0,8,"a"],["v","quantGroupSize",null,"public",23,23,[23,35],23,null,0,8,"a"],["v","quantBits",null,"public",24,24,[24,30],24,null,0,8,"a"]],"old":"","new":"//\n//  DinoVariant.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The DINOv2-small weight variants, smallest memory last: small (F32, 86 MB, the default),\n//        xsmall (F16, 43 MB), xxsmall (8-bit Linear weights in groups of 64, 23 MB; conv, norms and\n//        embeddings stay F16, and the model is quantized before its weights load).\n//\n\npublic enum DinoVariant: String, Sendable, Codable, CaseIterable {\n    case small, xsmall, xxsmall\n\n    public var weightFile: WeightFile {\n        switch self {\n        case .small: return .dinov2Small\n        case .xsmall: return .dinov2XSmall\n        case .xxsmall: return .dinov2XXSmall\n        }\n    }\n\n    public var isQuantized: Bool { self == .xxsmall }\n    public var quantGroupSize: Int { 64 }\n    public var quantBits: Int { 8 }\n}\n"},{"path":"Sources/VeilGardeLens/Semantic/Dinov2Preprocess.swift","status":"added","lang":"swift","hunks":[[1,0,1,60]],"header":{"lines":[1,13],"target":"VeilGardeLens","what":[6,9],"pin":[10,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":386,"scopes":[["E","Dinov2Preprocess",null,"public",19,19,[19,29],60,null,-1,0,"a",[]],["f","input",["_","target","shortEdge"],"public static",24,24,[24,97],44,[23,23],0,0,"a"],["f","inputNormalized",["_","normW","normH","target","shortEdge"],"public static",47,47,[47,143],50,[46,46],0,0,"a"],["f","resizeExact",["_","_","_"],"static",52,52,[52,75],59,null,0,0,"a"]],"old":"","new":"//\n//  Dinov2Preprocess.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A CGImage to the (1, 224, 224, 3) tensor DINOv2 reads: shortest edge to 256 with high\n//        quality interpolation, centre crop 224, /255, ImageNet mean and std. The specialist heads'\n//        variant first force-resizes the image to 360×640, so the source resolution cannot leak\n//        into the embedding (phone screenshots are huge, the training reels were small).\n//  PIN:  Garde's Dinov2Preprocess (HF BitImageProcessor replica). The camera head reads the plain\n//        path; every linear head reads the force-resized one: two different embeddings of one\n//        image, and the store keeps both (dino_fusion, dino_norm).\n//\n\nimport CoreGraphics\nimport Foundation\nimport MLX\n\npublic enum Dinov2Preprocess {\n    static let mean: [Float] = [0.485, 0.456, 0.406]\n    static let std: [Float] = [0.229, 0.224, 0.225]\n\n    /// Row 0 is the image's top: a bitmap context stores it so, and `draw` renders upright.\n    public static func input(_ cg: CGImage, target: Int = 224, shortEdge: Int = 256) -> MLXArray {\n        let w = cg.width, h = cg.height\n        let scale = Double(shortEdge) / Double(min(w, h))\n        let sw = Double(w) * scale, sh = Double(h) * scale\n        let cropX = (sw - Double(target)) / 2.0\n        let cropY = (sh - Double(target)) / 2.0\n        var buf = [UInt8](repeating: 0, count: target * target * 4)\n        guard let ctx = CGContext(data: &buf, width: target, height: target, bitsPerComponent: 8, bytesPerRow: target * 4,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else {\n            return MLXArray.zeros([1, target, target, 3])\n        }\n        ctx.interpolationQuality = .high\n        ctx.draw(cg, in: CGRect(x: -cropX, y: -cropY, width: sw, height: sh))\n        var floats = [Float](repeating: 0, count: target * target * 3)\n        for i in 0..<(target * target) {\n            floats[i * 3 + 0] = (Float(buf[i * 4 + 0]) / 255.0 - mean[0]) / std[0]\n            floats[i * 3 + 1] = (Float(buf[i * 4 + 1]) / 255.0 - mean[1]) / std[1]\n            floats[i * 3 + 2] = (Float(buf[i * 4 + 2]) / 255.0 - mean[2]) / std[2]\n        }\n        return MLXArray(floats, [1, target, target, 3])\n    }\n\n    /// The heads' input: force-resize to normW × normH (aspect not kept, PIL's resize), then `input`.\n    public static func inputNormalized(_ cg: CGImage, normW: Int = 360, normH: Int = 640, target: Int = 224, shortEdge: Int = 256) -> MLXArray {\n        guard let r = resizeExact(cg, normW, normH) else { return input(cg, target: target, shortEdge: shortEdge) }\n        return input(r, target: target, shortEdge: shortEdge)\n    }\n\n    static func resizeExact(_ cg: CGImage, _ w: Int, _ h: Int) -> CGImage? {\n        var buf = [UInt8](repeating: 0, count: w * h * 4)\n        guard let ctx = CGContext(data: &buf, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,\n                                  space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }\n        ctx.interpolationQuality = .high\n        ctx.draw(cg, in: CGRect(x: 0, y: 0, width: w, height: h))\n        return ctx.makeImage()\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Semantic/Dinov2ViT.swift","status":"added","lang":"swift","hunks":[[1,0,1,130]],"header":{"lines":[1,15],"target":"VeilGardeLens","what":[6,9],"pin":[10,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":390,"scopes":[["f","attention",["_","q","k","v","proj","heads","scale"],"private",21,21,[21,123],29,null,-1,0,"a"],["C","Dinov2Attention",null,"final",31,31,[31,36],49,null,-1,0,"a"],["i","init",["dims","heads"],"",39,39,[39,32],46,null,1,0,"a"],["f","callAsFunction",["_"],"",48,48,[48,51],48,null,1,8,"a"],["C","Dinov2MLP",null,"final",51,51,[51,30],61,null,-1,0,"a"],["i","init",["dims","hidden"],"",55,55,[55,33],58,null,4,0,"a"],["f","callAsFunction",["_"],"",60,60,[60,51],60,null,4,8,"a"],["C","Dinov2Block",null,"final",63,63,[63,32],84,null,-1,0,"a"],["i","init",["dims","heads","mlpHidden","eps"],"",71,71,[71,60],78,null,7,0,"a"],["f","callAsFunction",["_"],"",80,80,[80,51],83,null,7,0,"a"],["C","Dinov2ViT",null,"public final",86,86,[86,37],130,null,-1,0,"a"],["i","init",["hidden","layers","heads","patch","eps"],"public",93,93,[93,105],100,null,10,0,"a"],["f","tokens",["_"],"",103,103,[103,48],113,[102,102],10,0,"a"],["f","callAsFunction",["_"],"public",116,116,[116,63],118,[115,115],10,0,"a"],["f","patchTokens",["_"],"public",121,121,[121,60],123,[120,120],10,0,"a"],["f","loadWeights",["url"],"public",125,125,[125,45],129,null,10,0,"a"]],"old":"","new":"//\n//  Dinov2ViT.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: DINOv2-small (ViT-S/14) in MLXNN: the semantic half of VeilGarde. Its 384-value CLS embedding\n//        feeds the camera head (what the image depicts, beside whether a sensor made it), its\n//        256 patch tokens feed the semantic-tile head, and the same CLS after a 360×640\n//        force-resize feeds every specialist head.\n//  PIN:  Garde's port, unchanged: 12 blocks, 6 heads, MLP 1536, LayerScale, LayerNorm ε 1e-6,\n//        exact GELU, manual softmax attention, no register tokens, a fixed 224 input (16×16\n//        patches) with the position embedding pre-interpolated to [1, 257, 384] and the patch\n//        Conv2d stored [O, kH, kW, I]. The forward runs in the loaded weights' dtype (F32 small,\n//        F16 xsmall, int8 Linear xxsmall) and returns F32.\n//\n\nimport Foundation\nimport MLX\nimport MLXNN\n\nprivate func attention(_ x: MLXArray, q: Linear, k: Linear, v: Linear, proj: Linear, heads: Int, scale: Float) -> MLXArray {\n    let (B, L) = (x.dim(0), x.dim(1))\n    let qa = q(x).reshaped(B, L, heads, -1).transposed(0, 2, 1, 3)\n    let ka = k(x).reshaped(B, L, heads, -1).transposed(0, 2, 1, 3)\n    let va = v(x).reshaped(B, L, heads, -1).transposed(0, 2, 1, 3)\n    let scores = softmax(matmul(qa, ka.transposed(0, 1, 3, 2)) * scale, axis: -1)\n    let o = matmul(scores, va).transposed(0, 2, 1, 3).reshaped(B, L, -1)\n    return proj(o)\n}\n\nfinal class Dinov2Attention: Module {\n    let heads: Int\n    let scale: Float\n    @ModuleInfo(key: \"q\") var q: Linear\n    @ModuleInfo(key: \"k\") var k: Linear\n    @ModuleInfo(key: \"v\") var v: Linear\n    @ModuleInfo(key: \"proj\") var proj: Linear\n\n    init(dims: Int, heads: Int) {\n        self.heads = heads\n        self.scale = pow(Float(dims / heads), -0.5)\n        self._q.wrappedValue = Linear(dims, dims, bias: true)\n        self._k.wrappedValue = Linear(dims, dims, bias: true)\n        self._v.wrappedValue = Linear(dims, dims, bias: true)\n        self._proj.wrappedValue = Linear(dims, dims, bias: true)\n    }\n\n    func callAsFunction(_ x: MLXArray) -> MLXArray { attention(x, q: q, k: k, v: v, proj: proj, heads: heads, scale: scale) }\n}\n\nfinal class Dinov2MLP: Module {\n    @ModuleInfo(key: \"fc1\") var fc1: Linear\n    @ModuleInfo(key: \"fc2\") var fc2: Linear\n\n    init(dims: Int, hidden: Int) {\n        self._fc1.wrappedValue = Linear(dims, hidden, bias: true)\n        self._fc2.wrappedValue = Linear(hidden, dims, bias: true)\n    }\n\n    func callAsFunction(_ x: MLXArray) -> MLXArray { fc2(gelu(fc1(x))) }   // exact GELU\n}\n\nfinal class Dinov2Block: Module {\n    @ModuleInfo(key: \"norm1\") var norm1: LayerNorm\n    @ModuleInfo(key: \"attn\") var attn: Dinov2Attention\n    @ParameterInfo(key: \"ls1\") var ls1: MLXArray\n    @ModuleInfo(key: \"norm2\") var norm2: LayerNorm\n    @ModuleInfo(key: \"mlp\") var mlp: Dinov2MLP\n    @ParameterInfo(key: \"ls2\") var ls2: MLXArray\n\n    init(dims: Int, heads: Int, mlpHidden: Int, eps: Float) {\n        self._norm1.wrappedValue = LayerNorm(dimensions: dims, eps: eps)\n        self._attn.wrappedValue = Dinov2Attention(dims: dims, heads: heads)\n        self._ls1.wrappedValue = MLXArray.ones([dims])\n        self._norm2.wrappedValue = LayerNorm(dimensions: dims, eps: eps)\n        self._mlp.wrappedValue = Dinov2MLP(dims: dims, hidden: mlpHidden)\n        self._ls2.wrappedValue = MLXArray.ones([dims])\n    }\n\n    func callAsFunction(_ x: MLXArray) -> MLXArray {\n        let h = x + ls1 * attn(norm1(x))\n        return h + ls2 * mlp(norm2(h))\n    }\n}\n\npublic final class Dinov2ViT: Module {\n    @ModuleInfo(key: \"patch_embed\") var patchEmbed: Conv2d\n    @ParameterInfo(key: \"cls_token\") var clsToken: MLXArray\n    @ParameterInfo(key: \"pos_embed\") var posEmbed: MLXArray\n    let blocks: [Dinov2Block]\n    @ModuleInfo(key: \"norm\") var norm: LayerNorm\n\n    public init(hidden: Int = 384, layers: Int = 12, heads: Int = 6, patch: Int = 14, eps: Float = 1e-6) {\n        self._patchEmbed.wrappedValue = Conv2d(inputChannels: 3, outputChannels: hidden, kernelSize: .init(patch), stride: .init(patch))\n        self._clsToken.wrappedValue = MLXArray.zeros([1, 1, hidden])\n        self._posEmbed.wrappedValue = MLXArray.zeros([1, 16 * 16 + 1, hidden])\n        self.blocks = (0..<layers).map { _ in Dinov2Block(dims: hidden, heads: heads, mlpHidden: hidden * 4, eps: eps) }\n        self._norm.wrappedValue = LayerNorm(dimensions: hidden, eps: eps)\n        super.init()\n    }\n\n    /// The final-norm token sequence (B, 257, hidden) for NHWC ImageNet-normalized pixels.\n    func tokens(_ pixels: MLXArray) -> MLXArray {\n        let dt = clsToken.dtype\n        let B = pixels.dim(0)\n        var p = patchEmbed(pixels.asType(dt))\n        p = p.flattened(start: 1, end: 2)\n        let cls = broadcast(clsToken, to: [B, 1, clsToken.dim(2)])\n        var x = concatenated([cls, p], axis: 1)\n        x = x + posEmbed\n        for blk in blocks { x = blk(x) }\n        return norm(x)\n    }\n\n    /// The CLS embedding (B, hidden), F32.\n    public func callAsFunction(_ pixels: MLXArray) -> MLXArray {\n        tokens(pixels)[0..., 0..<1, 0...].squeezed(axis: 1).asType(.float32)\n    }\n\n    /// The patch tokens (B, 256, hidden), F32, CLS row excluded.\n    public func patchTokens(_ pixels: MLXArray) -> MLXArray {\n        tokens(pixels)[0..., 1..., 0...].asType(.float32)\n    }\n\n    public func loadWeights(url: URL) throws {\n        let w = try loadArrays(url: url)\n        try update(parameters: ModuleParameters.unflattened(w), verify: [.all])\n        eval(self)\n    }\n}\n"},{"path":"Sources/VeilGardeLens/Semantic/SemanticLens.swift","status":"added","lang":"swift","hunks":[[1,0,1,54]],"header":{"lines":[1,11],"target":"VeilGardeLens","what":[6,7],"pin":[8,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":406,"scopes":[["C","SemanticLens",null,"public final",18,18,[18,53],54,null,-1,0,"a"],["f","vit",["_"],"public",23,23,[23,73],32,null,0,0,"a"],["f","fusionEmbedding",["_","variant"],"public static",35,35,[35,103],37,[34,34],0,0,"a"],["f","normalizedEmbedding",["_","variant","normW","normH"],"public static",40,40,[40,143],42,[39,39],0,0,"a"],["f","patchTokens",["_","variant"],"public static",45,45,[45,133],48,[44,44],0,0,"a"],["f","embedding",["pixels","variant"],"public static",51,51,[51,99],53,[50,50],0,0,"a"]],"old":"","new":"//\n//  SemanticLens.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: DINOv2 as the layers above use it: the model loaded once per weight variant, and an image\n//        to its fusion embedding, its normalized (head) embedding, or its 256 patch tokens.\n//  PIN:  Garde's Dinov2Cache and embedding entry points. The xxsmall variant is quantized (its\n//        Linear slots made int8) before its weights load. Weights come from the WeightLocator;\n//        a missing file is an error naming where it was looked for, never a crash.\n//\n\nimport CoreGraphics\nimport Foundation\nimport MLX\nimport MLXNN\n\npublic final class SemanticLens: @unchecked Sendable {\n    public static let shared = SemanticLens()\n    private let lock = NSLock()\n    private var models: [DinoVariant: Dinov2ViT] = [:]\n\n    public func vit(_ variant: DinoVariant = .small) throws -> Dinov2ViT {\n        lock.lock()\n        defer { lock.unlock() }\n        if let m = models[variant] { return m }\n        let m = Dinov2ViT()\n        if variant.isQuantized { quantize(model: m, groupSize: variant.quantGroupSize, bits: variant.quantBits) }\n        try m.loadWeights(url: WeightLocator.shared.require(variant.weightFile))\n        models[variant] = m\n        return m\n    }\n\n    /// The camera head's embedding: CLS after the plain 256/224 preprocessing.\n    public static func fusionEmbedding(_ cg: CGImage, variant: DinoVariant = .small) throws -> [Float] {\n        try shared.vit(variant)(Dinov2Preprocess.input(cg)).reshaped(-1).asArray(Float.self)\n    }\n\n    /// The specialist heads' embedding: CLS after the normW × normH force-resize.\n    public static func normalizedEmbedding(_ cg: CGImage, variant: DinoVariant = .small, normW: Int = 360, normH: Int = 640) throws -> [Float] {\n        try shared.vit(variant)(Dinov2Preprocess.inputNormalized(cg, normW: normW, normH: normH)).reshaped(-1).asArray(Float.self)\n    }\n\n    /// The 256 patch tokens of the plain input, row-major [256 × 384].\n    public static func patchTokens(_ cg: CGImage, variant: DinoVariant = .small) throws -> (values: [Float], count: Int, width: Int) {\n        let toks = try shared.vit(variant).patchTokens(Dinov2Preprocess.input(cg))\n        return (toks.asArray(Float.self), toks.dim(1), toks.dim(2))\n    }\n\n    /// The CLS embedding of an already-preprocessed (1, 224, 224, 3) tensor (parity fixtures).\n    public static func embedding(pixels: [Float], variant: DinoVariant = .small) throws -> [Float] {\n        try shared.vit(variant)(MLXArray(pixels, [1, 224, 224, 3])).reshaped(-1).asArray(Float.self)\n    }\n}\n"},{"path":"Sources/VeilGardeLens/VeilGardeLens.swift","status":"added","lang":"swift","hunks":[[1,0,1,14]],"header":{"lines":[1,12],"target":"VeilGardeLens","what":[6,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":412,"scopes":[],"old":"","new":"//\n//  VeilGardeLens.swift\n//  VeilGardeLens\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The extractors: everything that turns an image's pixels into the numbers the models read,\n//        in the order a pixel travels (Image, Capture, Semantic, Scoring). Re-exports\n//        VeilGardeCore, so a layer above imports the Lens alone. The warp residual moved to the\n//        watermark on 2026-10-21, its only reader.\n//  PIN:  Every MLX symbol here comes from Frigate (MLX, MLXNN, MLXFFT, MLXAccelerate) and the tree\n//        evaluator is Frigate's XGBoostTreeModel; nothing Frigate provides is re-implemented.\n//\n\n@_exported import VeilGardeCore\n"}]};
